describe('Modal Accessibility Tests', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.get('button.open-modal').click(); // Replace with the actual selector to open the modal
    });

    it('should announce the modal title when opened', () => {
        const modalTitle = 'Expected Modal Title'; // Replace with the actual title of the modal
        cy.get('.modal') // Replace with the actual selector for the modal
            .should('be.visible')
            .find('.modal-title') // Replace with the actual selector for the title
            .should('have.text', modalTitle)
            .then(() => {
                cy.window().then((win) => {
                    const announcement = win.document.querySelector('.sr-only'); // Replace with the actual selector for the announcement
                    expect(announcement).to.exist;
                    expect(announcement.textContent).to.include(modalTitle);
                });
            });
    });

    it('should not announce the modal title if the modal is not opened', () => {
        cy.get('.modal') // Replace with the actual selector for the modal
            .should('not.exist')
            .then(() => {
                cy.window().then((win) => {
                    const announcement = win.document.querySelector('.sr-only'); // Replace with the actual selector for the announcement
                    expect(announcement).to.not.exist;
                });
            });
    });
});
